function patternAlphabetInvertedTriangle(n) {
  let alphabet = '';
  for (let i = 0; i < n; i++) alphabet += String.fromCharCode(65 + i);
  let rows = [];
  for (let i = 0; i < n; i++) {
    rows.push(alphabet.slice(0, n - i));
  }
  return rows.join('\n');
}
